import{_ as o,a0 as i,w as p,s as l,ao as d,I as a,x as e,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7","title":"Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務","tag":"201409","desc":""},"relativePath":"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7.md","filePath":"[post].md"}'),m={name:"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7.md"};function u(c,t,S,y,x,L){const s=i("Link");return p(),l("div",null,[t[13]||(t[13]=d(`<h1 id="linux-systemd-——-在rhel-centos-7中啓動-停止-重啓服務" tabindex="-1">Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務 <a class="header-anchor" href="#linux-systemd-——-在rhel-centos-7中啓動-停止-重啓服務" aria-label="Permalink to “Linux Systemd —— 在RHEL/CentOS 7中啓動/停止/重啓服務”">​</a></h1><p>RHEL/CentOS 7.0中一個最主要的改變，就是切換到了<strong>systemd</strong>。它用於替代紅帽企業版Linux前任版本中的SysV和Upstart，對系統和服務進行管理。systemd兼容SysV和Linux標準組的啓動腳本。</p><p><strong>Systemd</strong>是一個Linux操作系統下的系統和服務管理器。它被設計成向後兼容SysV啓動腳本，並提供了大量的特性，如開機時平行啓動系統服務，按需啓動守護進程，支持系統狀態快照，或者基於依賴的服務控制邏輯。</p><p>先前的使用SysV初始化或Upstart的紅帽企業版Linux版本中，使用位於/etc/rc.d/init.d/目錄中的bash初始化腳本進行管理。而在RHEL 7/CentOS 7中，這些啓動腳本被服務單元取代了。服務單元以.service文件擴展結束，提供了與初始化腳本同樣的用途。要查看、啓動、停止、重啓、啓用或者禁用系統服務，你要使用systemctl來代替舊的service命令。</p><blockquote><p>注：為了向後兼容，舊的service命令在CentOS 7中仍然可用，它會重定向所有命令到新的systemctl工具。</p></blockquote><h3 id="使用systemctl來啓動-停止-重啓服務" tabindex="-1">使用systemctl來啓動/停止/重啓服務 <a class="header-anchor" href="#使用systemctl來啓動-停止-重啓服務" aria-label="Permalink to “使用systemctl來啓動/停止/重啓服務”">​</a></h3><p>要啓動一個服務，你需要使用如下命令：</p><pre><code># systemctl start httpd.service
</code></pre><p>這會啓動httpd服務，就我們而言，Apache HTTP服務器。</p><p>要停掉它，需要以root身份使用該命令：</p><pre><code># systemctl stop httpd.service
</code></pre><p>要重啓，你可以使用restart選項，如果服務在運行中，它將重啓服務；如果服務不在運行中，它將會啓動。你也可以使用try-start選項，它只會在服務已經在運行中的時候重啓服務。同時，reload選項你也可以有，它會重新加載配置文件。</p><pre><code># systemctl restart httpd.service
# systemctl try-restart httpd.service
# systemctl reload httpd.service
</code></pre><p>我們例子中的命令看起來會像下面這樣：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-start-stop-restart.gif" alt="systemctl start-stop-restart"></p><h3 id="檢查服務狀態" tabindex="-1">檢查服務狀態 <a class="header-anchor" href="#檢查服務狀態" aria-label="Permalink to “檢查服務狀態”">​</a></h3><p>要檢查服務狀態，你可以使用status選項，看這裏：</p><pre><code># systemctl status httpd.service
</code></pre><p>輸出結果就像這樣：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-status.gif" alt="systemctl status"></p><p>它會告訴你運行中的服務的方方面面。</p><h3 id="使用啓用-禁用服務來控制開機啓動" tabindex="-1">使用啓用/禁用服務來控制開機啓動 <a class="header-anchor" href="#使用啓用-禁用服務來控制開機啓動" aria-label="Permalink to “使用啓用/禁用服務來控制開機啓動”">​</a></h3><p>你也可以使用enable/disable選項來控制一個服務是否開機啓動，命令如下：</p><pre><code># systemctl enable httpd.service
# systemctl disable httpd.service
</code></pre><p>輸出結果看這裏：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-enable.gif" alt="systemctl-enable"></p><p>雖然在過去的幾年中，對systemd的採用飽受爭議，然而大多數主流發行版都已經逐漸採用或打算在下一個發行版中採用它。所以，它是一個有用的工具，我們需要好好熟悉它。</p><hr>`,28)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),r(s,{href:"http://linoxide.com/linux-command/start-stop-services-systemd/"},{default:n(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/start-stop-services-systemd/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),r(s,{href:"http://linoxide.com/author/adriand/"},{default:n(()=>[...t[2]||(t[2]=[e("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),r(s,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[4]||(t[4]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),r(s,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const T=o(m,[["render",u]]);export{f as __pageData,T as default};
